{
    float timeLeft;
    Color baseColor;

    void Start() { baseColor = GetComponent<SpriteRenderer>().color; }
    public void Flash() { timeLeft = 0.3f; }

    void Update()
    {
        timeLeft -= Time.deltaTime;
        GetComponent<SpriteRenderer>().color = timeLeft > 0 ? Color.red : baseColor;
    }
